from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/1516479/000156459019007444/insy-10k_20181231.htm','Historical marketed products and formulation-specific pipeline. 2018 stages not carried forward as current; sublingual and nasal routes distinguished.')
b=ev('https://www.sec.gov/Archives/edgar/data/1516479/000156459018009934/insy-defa14a_20180430.htm','Historical pipeline identifies liposomal paclitaxel, ondansetron sublingual spray and earlier naloxone sublingual route separately from nasal.')
c=ev('https://syndros.com/','Current commercial SYNDROS offering distributed by Benuvia; historical INSYS developer role not current distributor ownership.')
rows=[('SUBSYS','Historical fentanyl sublingual spray; current global availability uncertain.',a,'unknown'),('SYNDROS','Dronabinol oral solution now supplied by Benuvia.',c,'commercial'),('INSYS cannabidiol oral solution','Historical synthetic-CBD formulation candidate.',a,'unknown'),('INSYS dronabinol inhalation formulation','Historical inhaled cannabinoid candidate.',a,'unknown'),('INSYS buprenorphine sublingual spray','Historical investigational opioid formulation.',a,'unknown'),('INSYS buprenorphine/naloxone sublingual spray','Historical combination formulation.',a,'unknown'),('INSYS naloxone nasal spray','Historical intranasal antagonist formulation.',a,'unknown'),('INSYS epinephrine nasal spray','Historical intranasal rescue formulation.',a,'unknown'),('INSYS rizatriptan nasal spray','Historical intranasal migraine formulation.',a,'unknown'),('INSYS naloxone sublingual spray','Earlier sublingual antagonist formulation.',b,'unknown'),('INSYS ondansetron sublingual spray','Earlier investigational antiemetic formulation.',b,'unknown'),('INSYS liposome-encapsulated paclitaxel','Historical anticancer formulation programme.',b,'unknown')]
products=[p(n,desc,src,life,typ='product' if n in ['SUBSYS','SYNDROS'] else 'development_program') for n,desc,src,life in rows]
d=ev('https://www.fda.gov/drugs/risk-evaluation-and-mitigation-strategies-rems/transmucosal-immediate-release-fentanyl-tirf-medicines','FDA confirms US TIRF production including SUBSYS discontinued September 30 2024; no global inference.')
products[0]['description']='Historical fentanyl sublingual spray; US production discontinued September 2024, global status unresolved.'
products[0]['evidence']=[a,d]
products[0]['attributes']={'us_production_status':'discontinued','us_discontinuation_date':'2024-09-30'}
co=dict(company_id='cmp_2899ff0e-1910-44c7-bf0d-e47d91d25ae6',products=products,evidence=[a,b,c,d],status='partial',coverage_note='Twelve historical formulation identities with continuing marketed SYNDROS verified at successor site. Partial: bankruptcy asset/licence chain, exact current global SUBSYS availability, marketed strengths and platform identities remain. Generic active ingredients not attributed as entire worldwide medicine portfolios. Multiple indications not duplicated; nasal versus sublingual naloxone separate formulations. Old investigational stages do not imply current research. Historical developer role retained without claiming current INSYS ownership or operation.')
(out/'batch-0320.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
